def _row(rid, otype, title, text, subtopic, branch, extra):
    meta = {
        "law_number": LAWNUM, "law_year": YEAR,
        "instrument": INSTRUMENT, "instrument_rank": "مرسوم بقانون",
        "gazette_ref": GAZETTE_REF, "gazette_date": GAZETTE_DATE,
        "issued_date": ISSUED_DATE,
        "source": "official_gazette_1811",
        "effective_rule": EFFECT_RULE,
        "effective_from_computed": EFFECT_COMPUTED,
        "effective_from_is_computed": True,
        "in_force_today": False,
        "repeals": sorted(REPEALED),
        "repeal_effective_with_law": True,
        "related_laws": ["legis-3-2006", "legis-61-2007", "legis-8-2016",
                         "legis-16-1960", "legis-17-1960", "legis-63-2015",
                         "legis-21-2015", "legis-1-2016", "legis-116-2013",
                         "legis-12-2020", "legis-80-2026", "legis-20-1981"],
    }
    meta.update(extra)
    return {
        "id": rid, "object_type": otype, "branch": branch,
        "topic": TOPIC, "subtopic": subtopic, "micro_issue": None,
        "title": title, "original_text": text,
        "normalized_text": normalize_text(text),
        "source_key": None, "verification_status": "source_verified",
        "metadata": meta, "authority_status": "source_authority",
        "usable_as_citation": True,
    }


