def build_records(branch):
    out = [_row(PREFIX + "preamble", "legislation_preamble",
                "ديباجة " + LONGTITLE + TITLE_MARK, DATA["preamble"],
                "ديباجة المرسوم", branch, dict(VISUAL, issuing=True))]
    for it in DATA["issuing"]:
        extra = dict(VISUAL, issuing=True, article_number=it["num"],
                     article_name=ARNAMES[it["num"]])
        if it["num"] == 4:
            extra["repeal_article"] = True
        if it["num"] == 5:
            extra["is_effective_article"] = True
            extra["signatories_text"] = DATA["signatories"]
        out.append(_row(PREFIX + "issue-%d" % it["num"], "legislation_issuing_article",
                        "المادة %s من مواد إصدار %s%s"
                        % (ARNAMES[it["num"]], INSTRUMENT, TITLE_MARK),
                        it["text"], "مواد الإصدار", branch, extra))
    for a in DATA["articles"]:
        out.append(_row(PREFIX + "m%d" % a["num"], "legislation_article",
                        "المادة (%d) — %s — %s%s"
                        % (a["num"], a["chapter"], SHORTNAME, TITLE_MARK),
                        a["text"], a["chapter"], branch,
                        dict(VISUAL, issuing=False, article_number=a["num"],
                             chapter=a["chapter"])))
    out.append(_row(PREFIX + "memo-1", "legislation_preamble",
                    "المذكرة الإيضاحية — " + LONGTITLE, DATA["memo"],
                    "المذكرة الإيضاحية", branch,
                    dict(TWOSRC, document_kind="explanatory_memorandum", issuing=False)))
    return out


def law_fingerprint(cur, prefixes):
    cur.execute("""SELECT md5(string_agg(original_text || '␟' || coalesce(normalized_text,''),
                                         '|' ORDER BY id))
                   FROM knowledge_objects
                   WHERE %s""" % " OR ".join("id LIKE %s" for _ in prefixes),
                tuple(p + "-%" for p in prefixes))
    return cur.fetchone()[0]


def mark_pending_repeal(cur, changed):
    note = ("أُلغي هذا القانون بالمادة الرابعة من المرسوم بقانون رقم (102) لسنة 2026 "
            "بإصدار قانون تنظيم الإعلام (الكويت اليوم، العدد 1811، 2026/10/4) — "
            "والإلغاء لا يسري إلا %s، فالقانون **نافذ حتى ذلك التاريخ**. "
            "لا يُوسم superseded اليوم، والنص لا يُمسّ. التوسيم النهائي في جولة لاحقة "
            "على نموذج §10 (لا يُمحى نص قط)." % EFFECT_RULE)
    for pref, (label, expected) in sorted(REPEALED.items()):
        cur.execute("""SELECT id, title, metadata FROM knowledge_objects
                       WHERE id LIKE %s ORDER BY id""", (pref + "-%",))
        rows = cur.fetchall()
        if len(rows) != expected:
            raise SystemExit("REPEAL_SCOPE_UNEXPECTED: %s = %d كائنًا (المتوقع %d) "
                             "— أوقفت الدفعة." % (pref, len(rows), expected))
        n = 0
        for rid, title, meta in rows:
            meta = meta or {}
            t = title or ""
            meta["pending_repeal"] = {
                "instrument": INSTRUMENT,
                "instrument_id": PREFIX + "issue-4",
                "gazette_ref": GAZETTE_REF,
                "publication_date": GAZETTE_DATE,
                "effective_rule": EFFECT_RULE,
                "effective_from_computed": EFFECT_COMPUTED,
                "effective_from_is_computed": True,
                "in_force_today": True,
                "replaced_by_law": PREFIX.rstrip("-"),
                "note": note,
                "recorded_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            }
            new_t = t if REPEAL_MARK in t else (t + REPEAL_MARK)
            cur.execute("""UPDATE knowledge_objects SET title=%s, metadata=%s,
                           updated_at=now() WHERE id=%s""",
                        (new_t, Jsonb(meta), rid))
            if new_t != t:
                changed.append(rid)
            n += 1
        print("  %s (%s): %d كائنًا وُسم pending_repeal (العنوان فقط — لا نص)"
              % (pref, label, n))


def mark_orphan_regulation(cur):
    """اللائحة التنفيذية لقانون 8/2016: لا يسمّيها المرسوم، فلا يُدَّعى إلغاؤها —
    تُسجَّل إشارة مرجعية في الميتاداتا وحدها (لا نص ولا عنوان، فلا فهرسة)."""
    cur.execute("SELECT id, metadata FROM knowledge_objects WHERE id LIKE %s",
                (ORPHAN_REGL + "-%",))
    rows = cur.fetchall()
    if not rows:
        print("  %s: لا كائنات — تُخطّى." % ORPHAN_REGL)
        return
    for rid, meta in rows:
        meta = meta or {}
        meta["parent_law_pending_repeal"] = {
            "parent_law": "legis-8-2016",
            "instrument": INSTRUMENT,
            "effective_rule": EFFECT_RULE,
            "effective_from_computed": EFFECT_COMPUTED,
            "note": ("القانون الأصلي (8/2016 تنظيم الإعلام الإلكتروني) أُلغي بالمادة "
                     "الرابعة من المرسوم بقانون 102/2026 اعتبارًا من بدء العمل به. "
                     "ولم يسمِّ المرسوم هذه اللائحة، فلا يُقرَّر هنا شيء عن مصيرها — "
                     "هذه إشارة مرجعية لا حكم."),
        }
        cur.execute("UPDATE knowledge_objects SET metadata=%s, updated_at=now() "
                    "WHERE id=%s", (Jsonb(meta), rid))
    print("  %s: %d كائنًا أُلحقت بها إشارة مرجعية (ميتاداتا فقط — لا فهرسة)"
          % (ORPHAN_REGL, len(rows)))


